def find_path(graph, start, goal):
    if start == goal:
        return [start]
    visited = {start: 1}
    stack = [(start, deque([start]))]
    while stack:
        node, path = stack.pop()
        if node == goal:
            return path + [goal]
        unvisited_neighbors = [n for n in graph[node] if not visited.get(n, False)]
        weights = [(compute_node_weight(n, graph, visited), n) for n in unvisited_neighbors]
        weights.sort(reverse=True)
        for weight, neighbor in weights:
            if neighbor not in visited:
                visited[neighbor] = visited[node] + 1
                path += [neighbor]
                stack.append((neighbor, path))
                break
    return None
